/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var logger = require( 'debug' );
var isLineStyleArray = require( '@stdlib/plot/base/assert/is-line-style-array' );
var isLineStyle = require( '@stdlib/plot/base/assert/is-line-style' );
var hasEqualValues = require( '@stdlib/array/base/assert/has-equal-values' );
var min = require( '@stdlib/math/base/special/fast/min' );
var copy = require( '@stdlib/array/base/copy' );
var join = require( '@stdlib/array/base/join' );
var linestyle2dasharray = require( '@stdlib/plot/base/linestyle2dasharray' );
var format = require( '@stdlib/string/format' );
var prop = require( './properties.js' );


// VARIABLES //

var debug = logger( 'line-chart:set:'+prop.name );


// MAIN //

/**
* Sets line styles.
*
* @private
* @param {(Array<string>|string)} value - input value
* @throws {TypeError} must be a string or an array of strings
* @returns {void}
*/
function set( value ) {
	var values;
	var marks;
	var isStr;
	var N;
	var i;

	isStr = isLineStyle( value );
	if ( !isStr && !isLineStyleArray( value ) ) {
		throw new TypeError( format( 'invalid assignment. `%s` must be a line style or an array of line styles. Value: `%s`.', prop.name, value ) );
	}
	if ( isStr ) {
		value = [ value ];
	}
	if ( !hasEqualValues( value, this[ prop.private ] ) ) {
		debug( 'Current value: [%s]. New value: [%s].', join( this[ prop.private ], ', ' ), join( value, ', ' ) );
		values = copy( value );
		marks = this.config.marks;
		N = min( marks.length, values.length );
		for ( i = 0; i < N; i++ ) {
			marks[ i ].encode.update.strokeDash.value = linestyle2dasharray( values[ i ] ); // eslint-disable-line max-len
		}
		this[ prop.private ] = values;
	}
}


// EXPORTS //

module.exports = set;
